async function loadRemote() {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/team_data?id=eq.${STORAGE_KEY}&select=data`, {
    headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${SUPABASE_KEY}` },
  });
  if (!res.ok) throw new Error(`Lecture Supabase échouée (${res.status})`);
  const json = await res.json();
  return json[0]?.data ?? null;
}

async function saveRemote(data) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/team_data`, {
    method: "POST",
    headers: {
      apikey: SUPABASE_KEY,
      Authorization: `Bearer ${SUPABASE_KEY}`,
      "Content-Type": "application/json",
      Prefer: "resolution=merge-duplicates",
    },
    body: JSON.stringify({ id: STORAGE_KEY, data }),
  });
  if (!res.ok) throw new Error(`Écriture Supabase échouée (${res.status})`);
}

const uid = () => Math.random().toString(36).slice(2, 10) + Date.now().toString(36);

function emptyTeam(name) {
  return { name, players: [], sessions: [], injuries: [], coachPin: null };
}

function emptyData() {
  return {
    activeTeamId: "r1",
    teams: {
      r1: emptyTeam("Équipe R1"),
      u19: emptyTeam("U19"),
    },
  };
}

// Convertit une ancienne sauvegarde (avant la fonctionnalité multi-équipes) vers le nouveau format.
function migrateData(raw) {
  if (!raw) return emptyData();
  if (raw.teams && raw.activeTeamId) return raw;
  if (raw.players) {
    return {
      activeTeamId: "r1",
      teams: {
        r1: { name: "Équipe R1", players: raw.players || [], sessions: raw.sessions || [], injuries: raw.injuries || [], coachPin: raw.coachPin || null },
        u19: emptyTeam("U19"),
      },
    };
  }
  return emptyData();
}

function fmtDate(d) {
  if (!d) return "";
  const dt = new Date(d + "T00:00:00");
  return dt.toLocaleDateString("fr-FR", { weekday: "short", day: "2-digit", month: "short", year: "numeric" });
}

function fmtClock(totalSeconds) {
  const s = Math.max(0, Math.floor(totalSeconds));
  const m = Math.floor(s / 60);
  const ss = s % 60;
  return `${String(m).padStart(2, "0")}:${String(ss).padStart(2, "0")}`;
}

/* ---------------------------------------------------------------
   CALCULS STATISTIQUES
--------------------------------------------------------------- */
// Calcule le temps écoulé sans nécessiter une écriture de sauvegarde à chaque seconde :
// le chrono ne persiste que son état (running / accumulated / startedAt), pas sa valeur en continu.
function getElapsedSeconds(clock) {
  if (!clock) return 0;
  if (clock.accumulated === undefined) return clock.elapsed || 0; // compat anciennes sauvegardes
  return clock.running && clock.startedAt ? clock.accumulated + (Date.now() - clock.startedAt) / 1000 : clock.accumulated;
}

function playingTimeForPlayer(session, playerId) {
  if (!session.matchData) return 0;
  const events = session.matchData.events.filter(
    (e) => e.playerId === playerId && (e.type === "in" || e.type === "out")
  );
  let total = 0, lastIn = null;
  events.sort((a, b) => a.timestamp - b.timestamp);
  for (const ev of events) {
    if (ev.type === "in") lastIn = ev.timestamp;
    if (ev.type === "out" && lastIn !== null) {
      total += ev.timestamp - lastIn;
      lastIn = null;
    }
  }
  if (lastIn !== null) {
    const nowElapsed = getElapsedSeconds(session.matchData.clock);
    total += Math.max(0, nowElapsed - lastIn);
  }
  return total;
}

// Temps de jeu depuis la dernière entrée sur le terrain (se réinitialise à chaque sortie) — sert aux paliers de charge.
function currentStintSeconds(session, playerId) {
  if (!session.matchData) return 0;
  const events = session.matchData.events
    .filter((e) => e.playerId === playerId && (e.type === "in" || e.type === "out"))
    .sort((a, b) => a.timestamp - b.timestamp);
  let lastIn = null;
  for (const ev of events) {
    if (ev.type === "in") lastIn = ev.timestamp;
    if (ev.type === "out") lastIn = null;
  }
  if (lastIn === null) return 0;
  return Math.max(0, getElapsedSeconds(session.matchData.clock) - lastIn);
}

function statEventsForPlayer(session, playerId) {
  if (!session.matchData) return [];
  return session.matchData.events.filter((e) => e.playerId === playerId);
}

